INSERT INTO "ConfiguracaoPonteira" ("modeloId", "pecaTuboId", "pecaChapaId", "createdAt", "updatedAt") SELECT m."id", tubo."id", chapa."id", CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM "Modelo" m JOIN "Peca" tubo ON tubo."codigo"=(SELECT p1."codigo" FROM "ModeloPeca" mp1 JOIN "Peca" p1 ON p1."id"=mp1."pecaId" WHERE mp1."modeloId"=m."id" AND p1."tipoMaterial"='PONTEIRA' ORDER BY p1."id" LIMIT 1) JOIN "Peca" chapa ON chapa."codigo"=(SELECT p2."codigo" FROM "ModeloPeca" mp2 JOIN "Peca" p2 ON p2."id"=mp2."pecaId" WHERE mp2."modeloId"=m."id" AND p2."tipoMaterial" IN ('PLASMA','CHAPA') ORDER BY p2."id" LIMIT 1) WHERE m."codigo"='AD1001' AND tubo."id" IS NOT NULL AND chapa."id" IS NOT NULL;
